import time

class RateLimiter:
    def __init__(self, max_requests=100, window_ms=60000, now_fn=None):
        self.max_requests = max_requests
        self.window_ms = window_ms
        self.now_fn = now_fn or (lambda: time.time() * 1000)
        self.clients = {}

    def _cleanup(self, client_id):
        now = self.now_fn()
        if client_id in self.clients:
            self.clients[client_id] = [
                t for t in self.clients[client_id]
                if now - t < self.window_ms
            ]

    def is_allowed(self, client_id: str) -> bool:
        self._cleanup(client_id)
        requests = self.clients.get(client_id, [])
        return len(requests) < self.max_requests

    def consume(self, client_id: str) -> dict:
        self._cleanup(client_id)
        if client_id not in self.clients:
            self.clients[client_id] = []

        requests = self.clients[client_id]
        allowed = len(requests) < self.max_requests

        if allowed:
            requests.append(self.now_fn())

        remaining = max(0, self.max_requests - len(requests))
        reset_time = requests[0] + self.window_ms if requests else self.now_fn() + self.window_ms

        return {
            'allowed': allowed,
            'remaining': remaining,
            'reset_time': reset_time
        }

    def get_remaining(self, client_id: str) -> int:
        self._cleanup(client_id)
        count = len(self.clients.get(client_id, []))
        return max(0, self.max_requests - count)

