class RateLimiter {
  constructor({ maxRequests = 100, windowMs = 60000, nowFn = Date.now } = {}) {
    this.maxRequests = maxRequests;
    this.windowMs = windowMs;
    this.nowFn = nowFn;
    this.clients = new Map();
  }

  _cleanup(clientId) {
    const now = this.nowFn();
    const requests = this.clients.get(clientId) || [];
    const valid = requests.filter(t => now - t < this.windowMs);
    this.clients.set(clientId, valid);
  }

  isAllowed(clientId) {
    this._cleanup(clientId);
    return (this.clients.get(clientId) || []).length < this.maxRequests;
  }

  consume(clientId) {
    this._cleanup(clientId);
    if (!this.clients.has(clientId)) this.clients.set(clientId, []);
    const requests = this.clients.get(clientId);
    const allowed = requests.length < this.maxRequests;

    if (allowed) requests.push(this.nowFn());

    const remaining = Math.max(0, this.maxRequests - requests.length);
    const resetTime = requests.length ? requests[0] + this.windowMs : this.nowFn() + this.windowMs;

    return { allowed, remaining, resetTime };
  }

  getRemaining(clientId) {
    this._cleanup(clientId);
    return Math.max(0, this.maxRequests - (this.clients.get(clientId) || []).length);
  }
}
